use std::{env,fs,io::{self,Write}};use spore_core::{creature_skin_crossing_v1::{refine,Admission},native_sse::Policy};
fn main(){let a:Vec<_>=env::args().collect();assert_eq!(a.len(),2);let b=fs::read(&a[1]).unwrap();assert_eq!(b.len(),200);let v:Vec<u32>=b.chunks_exact(4).map(|x|u32::from_le_bytes(x.try_into().unwrap())).collect();let mut out=Vec::new();for c in v.chunks_exact(10){let f=|i|f32::from_bits(c[i]);let start=[f(0),f(1),f(2)];let end=[f(3),f(4),f(5)];let root=f(8);let mode=c[9];let result=refine(start,end,f(6),f(7),Policy::Mxcsr1f80,|p|Some(if mode==0{root-p[0]}else{p[0]-root}),Admission).unwrap();let mut words=vec![result.t.to_bits()];words.extend(result.point.map(f32::to_bits));words.push(result.samples.len() as u32);for s in result.samples{words.extend(s.point.map(f32::to_bits));words.push(s.field.to_bits());}words.resize(85,0);for w in words{out.extend(w.to_le_bytes());}}io::stdout().write_all(&out).unwrap();}
